CREATE TABLE "public"."project_files" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_id"         bigint                   NOT NULL,
  "category"          text                     NOT NULL DEFAULT 'inne'::text,
  "file_name"         text                     NOT NULL,
  "file_path"         text                     NOT NULL,
  "file_url"          text                     NOT NULL,
  "file_type"         text,
  "comment"           text,
  "uploaded_by"       uuid,
  "uploaded_by_color" text,
  "uploaded_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "project_files_client_id_fkey" FOREIGN KEY (client_id) REFERENCES public.clients(id) ON DELETE CASCADE,
  CONSTRAINT "project_files_pkey" PRIMARY KEY (id),
  CONSTRAINT "project_files_uploaded_by_fkey" FOREIGN KEY (uploaded_by) REFERENCES public.profiles(id)
);

ALTER TABLE "public"."project_files"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "project_files_visible_project_access" ON "public"."project_files"
  FOR ALL
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.clients visible_client
  WHERE (visible_client.id = project_files.client_id))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.clients visible_client
  WHERE (visible_client.id = project_files.client_id))));

REVOKE ALL ON SEQUENCE "public"."project_files_id_seq" FROM "anon";

REVOKE ALL ON SEQUENCE "public"."project_files_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."project_files_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."project_files_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."project_files_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."project_files_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."project_files_id_seq" TO "service_role";

REVOKE ALL ON TABLE "public"."project_files" FROM "anon";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."project_files" TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."project_files" TO "service_role";

REVOKE ALL ON TABLE "public"."project_files" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."project_files" TO "postgres";
